-- Lot 228 : payloads 811 a 840 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-330","moteur":"chatgpt","payload":"[RaccourcIA — /galaxybody]\n\nMISSION\nFusionner une silhouette avec un univers galactique. Conserve contour et traits essentiels, loge la galaxie dans le volume et ajoute un liseré discret. Ne remplace pas le sujet par un simple ciel étoilé.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Silhouette cosmique » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Conserve contour et traits essentiels, loge la galaxie dans le volume et ajoute un liseré discret. Ne remplace pas le sujet par un simple ciel étoilé. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"408a61f49eaab7d28395e9f6942c5d6df301dd471765dd997ef775c85a52929a"},{"ref":"RCI-IMG-330","moteur":"claude","payload":"[RaccourcIA — /galaxybody]\n\nMISSION\nFusionner une silhouette avec un univers galactique. Conserve contour et traits essentiels, loge la galaxie dans le volume et ajoute un liseré discret. Ne remplace pas le sujet par un simple ciel étoilé.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Silhouette cosmique » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Conserve contour et traits essentiels, loge la galaxie dans le volume et ajoute un liseré discret. Ne remplace pas le sujet par un simple ciel étoilé. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme q